/* View: V_GRUPPENPFAD, Owner: SYSDBA */
CREATE VIEW V_GRUPPENPFAD (PFAD, OID) AS
 select A1.Bezeichnung ||'/'|| A2.Bezeichnung ||'/'|| A3.bezeichnung as Pfad, A3.OID from Artikelgruppen A1  left join Artikelgruppen A2 on A1.OID = A2.GID inner join Artikelgruppen A3 on A3.GID = A2.OID where A1.oid = A1.GID
;

/* View: V_STUECKLISTENPFAD, Owner: SYSDBA */
CREATE VIEW V_STUECKLISTENPFAD (PFAD, OID) AS
 select A1.Bezeichnung ||'/'|| A2.Bezeichnung  ||'/'|| A3.bezeichnung as Pfad, A3.OID from Stuecklistengruppen A1  left join Stuecklistengruppen A2 on A1.OID = A2.GID  inner join Stuecklistengruppen A3 on A3.GID = A2.OID where A1.oid = A1.GID;

/* View: V_BESTAND, Owner: SYSDBA */
CREATE VIEW V_BESTAND (ARTOID, BESTAND) AS


select Artoid, sum(Menge) from Lagerbuchung
group by Artoid
;

/* View: V_AUFTRAGOFFEN, Owner: SYSDBA */
CREATE VIEW V_AUFTRAGOFFEN (BELEGOID, NAME1, NAME2, NAME3, STRASSE, PLZ, ORT, NUMMER, ADRNR, ADROID, BELEGDATUM, VERTRETER, UNSKDNR, NUMMERALT, KONTRAKT, BEMERKUNG, GEDRUCKT, LIEFERTERMIN, BESTELLTERMIN, BESTELLNR, BEARBEITER, POSOID, POSNR, STCK, GELIEFERT, EPREIS, GPREIS, PREISEINHEIT, ARTOID, ARTNR, GEBUCHT, POSLIEFERTERMIN, REFOID, TEXT, POSTEXT) AS
 select 
B.OID as BelegOID,
B.name1,
B.name2,
B.name3,
b.Strasse,
B.Plz,
B.Ort,
B.nummer,
B.adrnr,
B.adroid,
B.Belegdatum,
B.Vertreter,
B.unskdnr,
B.nummeralt,
B.kontrakt,
B.bemerkung,
B.Gedruckt,
B.Liefertermin,
B.Bestelltermin,
B.Bestellnr,
B.Bearbeiter,

P.OID as PosOID,
P.posnr,
p.stck,
p.geliefert,
p.epreis,
p.Gpreis,
p.preiseinheit,
p.Artoid,
p.artnr,
p.gebucht,
p.liefertermin as PosLiefertermin,
p.refoid,
p.text,
p.Postext

 from Belegpos P
inner join Beleg B on 
  ( B.OID = P.Soid and B.abgeschlossen = 'F' and b.Belegart = 101 )
where  (Stck > 0)
 and ( ( geliefert < Stck ) or ( geliefert is NUll))
;

/* View: V_BESTELLUNGPOS, Owner: SYSDBA */
CREATE VIEW V_BESTELLUNGPOS (BELEGOID, NAME1, NAME2, NAME3, STRASSE, PLZ, ORT, BELEGDATUM, NUMMER, ADRNR, ADROID, ABGESCHLOSSEN, LIEFERTERMINBELEG, POSOID, SOID, POSNR, STCK, PREISEINHEIT, BESTELLMENGE, EPREIS, RABATT, ARTNR, EINHEIT, POS, MWST, KZ, GPREIS, ORGPREIS, ORGEK, ARTOID, GELIEFERT, BESTELLNR, GEBUCHT, LIEFERTERMINPOS, LIEFERTERMINSOLL, ABTERMIN) AS

select 
  OID,
  NAME1,
  NAME2,
  NAME3,
  Strasse,
  Plz,
  Ort,
  Belegdatum,
  Nummer,
  ADRNR,
  ADROID,
  ABGESCHLOSSEN,
  B.LIEFERTERMIN,

  P.OID,
  SOID,
  POSNR,
  STCK,
  Preiseinheit,
  PreisPreiseinheit,
  EPREIS,
  RABATT,
  ARTNR,
  EINHEIT,
  POS,
  MWST,
  KZ,
  GPREIS,
  ORGPREIS,
  ORGEK,
