  AbTermin

  from Belegpos P, Beleg B
    where P.SOID = B.OID and not Artoid is null and B.Belegart = '105'
;

/* View: V_AUFTRAGLIEFERUNG, Owner: SYSDBA */
CREATE VIEW V_AUFTRAGLIEFERUNG (BELEGOID, NAME1, NAME2, NAME3, STRASSE, PLZ, ORT, BELEGDATUM, NUMMER, ADRNR, ADROID, ABGESCHLOSSEN, LIEFERTERMINBELEG, POSOID, SOID, POSNR, STCK, PREISEINHEIT, BESTELLMENGE, EPREIS, RABATT, ARTNR, TEXT, POSTEXT, EINHEIT, POS, MWST, KZ, GPREIS, ORGPREIS, ORGEK, ARTOID, GELIEFERT, BESTELLNR, GEBUCHT, LIEFERTERMINPOS, LIEFERTERMINSOLL, ABTERMIN, REFOID) AS

select 
  OID,
  NAME1,
  NAME2,
  NAME3,
  Strasse,
  Plz,
  Ort,
  Belegdatum,
  Nummer,
  ADRNR,
  ADROID,
  ABGESCHLOSSEN,
  B.LIEFERTERMIN,

  P.OID,
  SOID,
  POSNR,
  STCK,
  Preiseinheit,
  PreisPreiseinheit,
  EPREIS,
  RABATT,
  ARTNR,
  Text,
  Postext,
  EINHEIT,
  POS,
  MWST,
  KZ,
  GPREIS,
  ORGPREIS,
  ORGEK,
  ARTOID,
  GELIEFERT,
  BESTELLNR,
  Gebucht,
  P.Liefertermin,
  Lieferterminsoll,
  AbTermin,
  RefOID
  from Belegpos P 
  Left Join Beleg B on B.OID = P.SOID
  Where P.REFOID > 0
;

/* View: V_BELEGPOS_ART, Owner: SYSDBA */
CREATE VIEW V_BELEGPOS_ART (OID, SOID, POSNR, STCK, PREISEINHEIT, PREISPREISEINHEIT, EPREIS, RABATT, ARTNR, EINHEIT, POS, MWST, KZ, GPREIS, ORGPREIS, ORGEK, ARTOID, GELIEFERT, BESTELLNR, BELEGART, ABGESCHLOSSEN, GEBUCHT, LIEFERTERMIN, LIEFERTERMINSOLL, ABTERMIN) AS

select 
OID,
  SOID,
  POSNR,
  STCK,
  Preiseinheit,
  PreisPreiseinheit,
  EPREIS,
  RABATT,
  ARTNR,
  EINHEIT,
  POS,
  MWST,
  KZ,
  GPREIS,
  ORGPREIS,
  ORGEK,
  ARTOID,
  GELIEFERT,
  BESTELLNR,
  B.Belegart, 
  B.Abgeschlossen,
  Gebucht,
  Liefertermin,
  Lieferterminsoll,
  AbTermin
  from Belegpos P, Beleg B
  where P.SOID = B.OID
   and not Artoid is null
;

/* View: V_ARTIKELAUFTRAG, Owner: SYSDBA */
CREATE VIEW V_ARTIKELAUFTRAG (NUMMER, HAUPTAUFTRAG, ADRNR, STCK, ARTNR, ARTOID) AS

select 
  Nummer,
  HAUPTAUFTRAG,
  ADRNR,
  Stck,
  ARTNR,
  ArtOID
  from Belegpos P, Beleg B
    where P.SOID = B.OID and not Artoid is null and B.Belegart = '101'
;

/* View: V_RAHMENAUFTRAGPOS, Owner: SYSDBA */
CREATE VIEW V_RAHMENAUFTRAGPOS (BELEGOID, NAME1, NAME2, NAME3, STRASSE, PLZ, ORT, BELEGDATUM, BELEGBEZ, NUMMER, ADRNR, ADROID, ABRUFMENGE, RESTMENGE, ABGESCHLOSSEN, LIEFERTERMINBELEG, BESTELLTERMIN, BESTELLNRBELEG, ARTIKELOID, STCK, REST, EPREIS, ARTNR, TEXT1, TEXT2) AS

select 
  B.OID,
  NAME1,
  NAME2,
  NAME3,
  Strasse,
  Plz,
  Ort,
  Belegdatum,
  Belegbez,
  B.Nummer,
  ADRNR,
  ADROID,
  Abrufmenge,
  Restmenge,
  ABGESCHLOSSEN,
  B.LIEFERTERMIN,
  B.Bestelltermin,
  B.Bestellnr,
  B.AbrufArtikel,
  B.Abrufmenge,
  B.Restmenge,
  B.Abrufpreis,
  A.Artnr,
  A.Bezeichnung1,
  A.Bezeichnung2
  from Beleg B, Artikel A
    where A.OID = B.AbrufArtikel and B.Belegart = '72'
;

/* View: V_RAHMENPOSOID, Owner: SYSDBA */
CREATE VIEW V_RAHMENPOSOID (BELEGOID, NAME1, NAME2, NAME3, STRASSE, PLZ, ORT, BELEGDATUM, BELEGBEZ, NUMMER, ADRNR, ADROID, ABRUFMENGE, RESTMENGE, ABGESCHLOSSEN, LIEFERTERMIN, BESTELLTERMIN, BESTELLNR, PREIS, POSOID) AS

select 
  B.OID,
  B.NAME1,
  B.NAME2,
  B.NAME3,
  B.Strasse,
  B.Plz,
  B.Ort,
  B.Belegdatum,
  B.Belegbez,
  B.Nummer,
  B.ADRNR,
  B.ADROID,
  B.Abrufmenge,
  B.Restmenge,
  B.ABGESCHLOSSEN,
  B.LIEFERTERMIN,
  B.Bestelltermin,
  B.Bestellnr,
  B.Abrufpreis,
  P.OID
  
  from Beleg B, Belegpos P 
    where P.SOID = B.OID and B.Belegart = '72'
;

/* View: V_BESTELLSUMMEN, Owner: SYSDBA */
CREATE VIEW V_BESTELLSUMMEN (ARTOID, BESTELLT, GELIEFERT) AS


select Artoid, sum(stck) as Bestellt, sum(Geliefert) as Geliefert from Belegpos P, Beleg B
  where B.Abgeschlossen ='F' and B.OID = P.SOID and B.Belegart = 105
  and ( (P.Gebucht is NULL) or (P.Gebucht = 'F') )
group by Artoid
;

/* View: V_PRODRESERVIERUNG, Owner: SYSDBA */
CREATE VIEW V_PRODRESERVIERUNG (PRODOID, KW, JAHR, PRODMENGE, STATUS, AUFTRAGOID, AUFTRAGNUMMER, BEGINNDATUM, KUNDE, KUNDENR, LIEFERTERMIN, STUECKNUMMER, ARTNR, BEZEICHNUNG1, BEZEICHNUNG2) AS



select P.OID, P.KW, P.Jahr, P.Menge, P.Status,
  A.OID, A.Nummer, P.Beginndatum, A.name1, A.Adrnr, A.Liefertermin, 
  P.ARTOID, S.Nummer,
  S.Bezeichnung1, S.Bezeichnung2
from ProduktionBereit P, Beleg A, Stuecklisten S
where 
 S.OID = P.ArtOID  and A.OID = P.AuftragOID
;

/* View: V_VERTRETER, Owner: SYSDBA */
CREATE VIEW V_VERTRETER (VERTRETERNAME1, VERTRTERNAME2, VERTRETERSTRASSE, VERTRETERPLZ, VERTRETERORT, VERTRETERNR, BELEGOID, BELEGMWST, BELEGNUMMER, BELEGDATUM, AUFTRAGANUMMER, RECHDATUM, KUNDENR, KUNDENAME, RECHBETRAG, STCK, EPREIS, PROVPOS, BELEGPROVISION, BETRAGPOS, ARTNR, BETRAGBELEG) AS


select 
A.Name1,
A.name2,
A.strasse,
A.plz,
A.ort,
A.OID,
B.OID,
B.MWSTSATZ,
B.nummer, 
B.Belegdatum,
B.hauptauftrag, 
B.Belegdatum, 
B.AdrNr,
B.name1, 
P.Gpreis, 
P.Stck,
P.Epreis,
P.provision as PProv,
B.Provision as BelegProvision, 
P.Gpreis*P.Provision/100, 
P.Artnr,
P.Gpreis*B.Provision/100

from Beleg B, Belegpos P 
join Adressen A on A.OID = B.Vertreter
where
B.Belegart = 103 and B.Vertreter > 0
and P.Soid = B.OID
;

/* View: V_VERTRETERPROV, Owner: SYSDBA */
CREATE VIEW V_VERTRETERPROV (RECHNUMMER, AUFTRAGANUMMER, RECHDATUM, KUNDE, RECHBETRAG, PROVPOS, PROVBELEG, BETRAGPOS, BETRAGBELEG) AS


select B.nummer, B.hauptauftrag, B.Belegdatum, B.name1, P.Gpreis, P.provision as PProv,
  B.Provision as BProv, P.Gpreis*P.Provision/100, P.Gpreis*B.Provision/100
  from Beleg B, Belegpos P where
B.Belegart = 103 and B.Vertreter > 0
and P.Soid = B.OID
;

/* View: V_STUECKLISTENARTIKEL, Owner: SYSDBA */
CREATE VIEW V_STUECKLISTENARTIKEL (STOID, STNUMMER, STBEZEICHNUNG1, STBEZEICHNUNG2, STARTTEXT, STARTOID, ARTIKELOID, AOID, ARTNR, EINHEIT, ABEZEICHNUNG1, ABEZEICHNUNG2, ANZAHL, POS, ARTTEXT, ASOID) AS

Select
  s.OID,
  s.NUMMER,
  s.Bezeichnung1,
  s.Bezeichnung2,
  s.ArtText,
  s.ArtOID,
  A.ArtOID,
  a.OID,
  a.Artnr,
  a.Einheit,
  A.Bezeichnung1,
  A.Bezeichnung2,
  a.Anzahl,
  a.eknetto,
  a.ArtText,
  a.ASOID
from stuecklisten s, stuecklistenartikel a 
  where s.oid = a.soid
;

/* View: V_LIEFREFOID, Owner: SYSDBA */
CREATE VIEW V_LIEFREFOID (OID, SOID, POSNR, STCK, EPREIS, RABATT, TEXT, ARTNR, EINHEIT, POS, ZWSUMME, MWST, KZ, POSTEXT, GPREIS, ORGPREIS, ORGEK, ARTOID, POSSORT, BESTELLNR, GELIEFERT, TAGE, LIEFERTERMIN, LIEFERTERMINSOLL, LIEFERPREIS, NACHLIEFERTERMIN, GEBUCHT, RAHMENOID, RAHMENTEXT, ABTERMIN, PROVISION, PREISEINHEIT, PREISPREISEINHEIT, LAGERORT, REFOID, ABNR, ABRAHMEN, RECHFREIGABE, AUSSCHUSSMENGE, FALSCHLIEFERMENGE, RGNRLIEF, RGNRINTERN) AS

select P.* from Belegpos P, Beleg B where
  B.Belegart= 102 and B.oid=P.soid and Stck > 0
;

/* View: V_PRODMATERIAL, Owner: SYSDBA */
CREATE VIEW V_PRODMATERIAL (PRODOID, KW, JAHR, PRODMENGE, FERTIG, STATUS, AUFTRAGOID, AUFTRAGNUMMER, BEGINNDATUM, KUNDE, KUNDENR, LIEFERTERMIN, STUECKNUMMER, ARTOID, ARTNR, BEZEICHNUNG1, BEZEICHNUNG2, ANZAHL, SOLLMENGE, BUCHMENGE, EINHEITMENGE, ASOID, MATOID, ZELLE) AS



select P.OID, P.KW, P.Jahr, P.Menge, P.Fertig, P.Status,
  A.OID, A.Nummer, P.Beginndatum, A.name1, A.Adrnr, A.Liefertermin, 
  S.Nummer,
  M.Artoid, M.Artnr, M.Bezeichnung1, M.Bezeichnung2,
  M.Anzahl, M.Sollmenge, M.Buchmenge,
  M.einheitmenge, M.ASOID, M.OID, M.Zelle

from Produktion P
  join Beleg A on A.OID = P.AuftragOID
  join Stuecklisten S on S.oid = P.Artoid
  left join Prodartikel M on (m.Soid = P.OID )
;

/* View: V_ARTIKELBUCHUNG, Owner: SYSDBA */
CREATE VIEW V_ARTIKELBUCHUNG (ARTOID, BELEGOID, DATUM, ARTNR, BELEGNUMMER, BELEGDATUM, BELEG, MENGE, BEMERKUNG, LIEFERTERMIN) AS

select L.ArtOID, L.BelegOID, L.Datum, A.Artnr, B.Nummer, 
  B.Belegdatum, B.Belegbez,  L.Menge, L.Bemerkung,
  bp.Liefertermin

from Lagerbuchung L

left join Artikel A on L.Artoid = A.Oid
left Join Beleg B on B.Oid = L.BelegOID
left join Belegpos bp on bp.oid = l.posOID

where L.Storno = 'F'
;

/* View: V_ARTIKELBAUFORM, Owner: SYSDBA */
CREATE VIEW V_ARTIKELBAUFORM (BAUFORMID, ARTOID, ARTNR, BEZEICHNUNG1, BEZEICHNUNG2, BAUFORM, BREITE, HOEHE, LAENGE, PINS, TYP, ZEIT, RUESTZEIT) AS

select A.Bauform, A.OID, A.Artnr, A.Bezeichnung1, A.Bezeichnung2, B.Bauform as BauformBezeichnung, B.Breite, B.hoehe, B.Laenge,
  B.Pins, B.Typ, b.zeit, B.ruestzeit from Artikel A 
  left join Bauformen B on B.oid = A.Bauform
;

/* View: V_ARTIKELAUFTRAGS, Owner: SYSDBA */
CREATE VIEW V_ARTIKELAUFTRAGS (NUMMER, BELEGOID, HAUPTAUFTRAG, ADRNR, STCK, ARTNR, ARTOID, STUECKOID) AS

select 
  B.Nummer,
  B.OID,
  HAUPTAUFTRAG,
  ADRNR,
  Stck,
  ARTNR,
  ArtOID,
  S.OID
  from Belegpos P, Beleg B
   inner join Stuecklisten S on S.Artoid = P.Artoid
    where P.SOID = B.OID and not Artoid is null and B.Belegart = '101'
;

/* View: V_BESTELLTERMINE, Owner: SYSDBA */
CREATE VIEW V_BESTELLTERMINE (ARTOID, BESTELLT, DATUM, SOLLDATUM, ABNR) AS


select Artoid, stck as Bestellt, ABTermin, LieferTerminSoll, ABNR from Belegpos P, Beleg B
