/* View: V_BEREIT0, Owner: SYSDBA */
CREATE VIEW V_BEREIT0 (PRODOID, KW, JAHR, PRODMENGE, ARTOID, ASOID, ANZAHL, NOSPLIT) AS



select P. OID, P.KW, P.Jahr, P.Menge, 
  M.Artoid, M.ASOID, M.Anzahl, NoSplit

from ProduktionBereit P, Beleg A, Stuecklisten S, Stuecklistenartikel M

where 
  ( P.Status is null or P.Status > -1 ) and
