;

/* View: V_LIEFPOS, Owner: SYSDBA */
CREATE VIEW V_LIEFPOS (BELEGOID, NAME1, NAME2, NAME3, STRASSE, PLZ, ORT, BELEGDATUM, BELEGBEZ, NUMMER, ADRNR, ADROID, ABGESCHLOSSEN, LIEFERTERMINBELEG, BESTELLTERMIN, BESTELLNRBELEG, POSOID, SOID, POSNR, STCK, PREISEINHEIT, PREISPREISEINHEIT, EPREIS, RABATT, ARTNR, TEXT, POSTEXT, EINHEIT, POS, MWST, KZ, GPREIS, ORGPREIS, ORGEK, ARTOID, GELIEFERT, BESTELLNR, GEBUCHT, LIEFERTERMINPOS, LIEFERTERMINSOLL, ABTERMIN, REFOID, RAHMENOID) AS

