/* View: V_BESTELLTERMINEPREIS, Owner: SYSDBA */
CREATE VIEW V_BESTELLTERMINEPREIS (ARTOID, BESTELLT, DATUM, SOLLDATUM, ABNR, EPREIS) AS


select Artoid, stck as Bestellt, ABTermin, LieferTerminSoll, ABNR, EPreis from Belegpos P, Beleg B
  where B.Abgeschlossen ='F' and B.OID = P.SOID and B.Belegart = 105
  and (P.Gebucht is NULL or P.Gebucht ='F') and not Artoid is NULL
;

/* View: V_UNTERBAUGRUPPE0, Owner: SYSDBA */
CREATE VIEW V_UNTERBAUGRUPPE0 (STUECKOID, STUECKARTOID, STUECKNUMMER, STUECKBEZEICHNUNG, UNTERBAUNUMMER, UNTERBAUBEZ1, UNTERBAUBEZ2, UNTERBAUANZAHL, UNTERBAUARTOID, UNTERBAUSTUECKOID) AS

select

  S.OID, 
  S.ArtOID,
  S.NUMMER,
  S.Bezeichnung1,
  A.Artnr,
  A.Bezeichnung1,
  A.Bezeichnung2,
  A.Anzahl,
  A.ArtOID,
  A.ASOID


 from StuecklistenArtikel A, Stuecklisten S where A.SOID = S.OID and 
   (not A.ASOID is NULL or A.ASOID > 0)
;

