CREATE VIEW V_UNTERBAUGRUPPE4 (STUECKOID, STUECKARTOID, STUECKNUMMER, STUECKBEZEICHNUNG, UNTERBAUNUMMER, UNTERBAUBEZ1, UNTERBAUBEZ2, UNTERBAUANZAHL, UNTERBAUARTOID, UNTERBAUSTUECKOID) AS

