/* View: V_ARTIKELRECHNUNG, Owner: SYSDBA */
CREATE VIEW V_ARTIKELRECHNUNG (NUMMER, HAUPTAUFTRAG, BELEGDATUM, ADRNR, ADROID, NAME1, NAME2, NAME3, STRASSE, PLZ, ORT, BELEGBEZ, ABGESCHLOSSEN, STCK, EPREIS, PREISEINHEIT, PREISPREISEINHEIT, ARTNR, TEXT, POSTEXT, ARTOID, REFOID, GPREIS, BRUTTO, NETTO, PROVISIONBELEG, PROVISIONPOS, VERTRETER) AS


select
