  ADRNR,
  ADROID,
  NAME1,
  NAME2,
  NAME3,
  STRASSE,
  PLZ,
  ORT,
  BELEGBEZ,
  ABGESCHLOSSEN,
  P.STCK,
  P.Epreis,
  PREISEINHEIT,
  PREISPREISEINHEIT,
  P.Artnr,
  P.TEXT,
  P.POSTEXT,
  P.ArtOID,
  P.RefOID,
  P.GPreis,
