/* View: V_ARTIKELLIEFERSCHEIN, Owner: SYSDBA */
CREATE VIEW V_ARTIKELLIEFERSCHEIN (NUMMER, HAUPTAUFTRAG, BELEGDATUM, ADRNR, ADROID, NAME1, NAME2, NAME3, STRASSE, PLZ, ORT, BELEGBEZ, ABGESCHLOSSEN, STCK, EPREIS, PREISEINHEIT, PREISPREISEINHEIT, ARTNR, TEXT, POSTEXT, ARTOID, REFOID) AS


select 
  Nummer,
  HauptAuftrag,
  Belegdatum,
  ADRNR,
  ADROID,
  NAME1,
  NAME2,
  NAME3,
  STRASSE,
  PLZ,
  ORT,
  BELEGBEZ,
  ABGESCHLOSSEN,
  Stck,
  EPreis,
  PREISEINHEIT,
  PREISPREISEINHEIT,
  ARTNR,
  Text,
  PosText,
  ArtOID,
  REFOID
  from Belegpos P, Beleg B
    where P.SOID = B.OID and not Artoid is null and B.Belegart = '102'
;

/* View: V_BEREIT1, Owner: SYSDBA */
CREATE VIEW V_BEREIT1 (PRODOID, KW, JAHR, PRODMENGE, PRODANZAHL, NOSPLIT, ARTOID, ASOID, ARTMENGE) AS
 select  V.ProdOID,  V.kw,  V.jahr,   V.prodmenge,  V.Anzahl*V.Anzahl,  V.NoSplit,  M.ARTOID,  M.ASOID,  M.Anzahl from v_bereit0 V,   stuecklistenartikel m where   M.SOID = V.ASOID and ( V.NoSplit is NULL or V.NoSplit <> 'T');

/* View: V_BEREIT2, Owner: SYSDBA */
CREATE VIEW V_BEREIT2 (PRODOID, KW, JAHR, PRODMENGE, PRODANZAHL, NOSPLIT, ARTOID, ASOID, ARTMENGE) AS
 select  V.ProdOID,  V.kw,  V.jahr,   V.prodmenge,  V.ProdAnzahl*V.Artmenge,  V.NoSplit,  M.ARTOID,  M.ASOID,  M.Anzahl from v_bereit1 V,   stuecklistenartikel m where   M.SOID = V.ASOID and ( V.NoSplit is NULL or V.NoSplit <> 'T');

/* View: V_BEREIT3, Owner: SYSDBA */
CREATE VIEW V_BEREIT3 (PRODOID, KW, JAHR, PRODMENGE, PRODANZAHL, NOSPLIT, ARTOID, ASOID, ARTMENGE) AS
 select  V.ProdOID,  V.kw,  V.jahr,   V.prodmenge,  V.ProdAnzahl*V.Artmenge,  V.NoSplit,  M.ARTOID,  M.ASOID,  M.Anzahl from v_bereit2 V,   stuecklistenartikel m where   M.SOID = V.ASOID and ( V.NoSplit is NULL or V.NoSplit <> 'T');

