/* View: V_PRODSTATUS, Owner: SYSDBA */
CREATE VIEW V_PRODSTATUS (PRODOID, KW, JAHR, PRODMENGE, FERTIG, STATUSOID, STATUS, AUFTRAGOID, AUFTRAGNUMMER, BEGINNDATUM, KUNDE, KUNDENR, LIEFERTERMIN, STUECKNUMMER, ARTOID) AS



select P.OID, P.KW, P.Jahr, P.Menge, P.Fertig, P.Status, K.Bezeichnung,
  A.OID, A.Nummer, P.Beginndatum, A.name1, A.Adrnr, A.Liefertermin, 
  S.Nummer, S.OID
from Produktion P
 left Join KonstProdStatus K on K.OID = P.Status
 left Join Stuecklisten S on S.OID = P.Artoid
 left Join Beleg A on A.OID = P.AuftragOID
;

/* View: V_BEARBEITERANG, Owner: SYSDBA */
CREATE VIEW V_BEARBEITERANG (BEARBEITER, ANGEBOT) AS
 select Bearbeiter,sum(Netto2) as Angebot from beleg where belegart = 100  group by bearbeiter 
;

/* View: V_BEREITMATERIAL, Owner: SYSDBA */
CREATE VIEW V_BEREITMATERIAL (PRODOID, KW, JAHR, PRODMENGE, AUFTRAGOID, AUFTRAGNUMMER, KUNDE, KUNDENR, LIEFERTERMIN, STUECKNUMMER, STUECKOID, ARTOID, ARTNR, BEZEICHNUNG1, BEZEICHNUNG2, ANZAHL, ASOID, NOSPLIT) AS



select P. OID, P.KW, P.Jahr, P.Menge- coalesce(P.Uebernommen, 0), 
  A.OID, A.Nummer, A.name1, A.Adrnr, A.Liefertermin, 
  S.Nummer, S.OID,
  M.Artoid, M.Artnr, M.Bezeichnung1, M.Bezeichnung2,
  M.Anzahl, M.ASOID, NoSplit

from ProduktionBereit P, Beleg A, Stuecklisten S, Stuecklistenartikel M

where 
  ( P.Status is null or P.Status > -1 ) and
  S.OID = M.Soid and S.OID = P.ArtOID  and A.OID = P.AuftragOID
;

