/* View: TELEFON, Owner: SYSDBA */
CREATE VIEW TELEFON (ANREDE, FIRMA, NAME1, NAME2, STRASSE, PLZ, ORT, FON1, FAX1, MOBIL) AS

with AllAdr as ( 
   Select A.Anrede, A.Name1 as Firma, A.Name1, A.Name2, A.Strasse, A.PLz, A.Ort, A.Fon1, A.Fax1, A.Mobil from Adressen A  
    union 
   Select N.Anrede as Anrede, MA.Name1 as Firma, N.Vorname as name1, N.Name as Name2, MA.Strasse, MA.PLz, MA.Ort, N.Tele1 as Fon1, N.Fax1 as Fax1,
     N.Mobil as Mobil from AdressenAnsprech N, Adressen MA where MA.oid = N.SOID
    ) 
    Select Anrede, Name1 as Firma, Name1, Name2, Strasse, PLz, Ort, 
    Fon1 as Fon1, 
     Fax1 AS Fax1, 
   Mobil as Mobil from Alladr where (coalesce(fon1, '') <>  '' ) or
    (coalesce(mobil,  '' ) <> '') and (coalesce(Firma, '') <> '' ) 
    order by 2
;

