RETURNS (OID INTEGER,
NAME1 VARCHAR(60) CHARACTER SET NONE,
BELEGDATUM D_DATE,
NUMMER INTEGER,
ADRNR INTEGER,
ADROID INTEGER,
POID INTEGER,
SOID INTEGER,
