ALTER PROCEDURE P_RECHNUNGFAELLIG (AOID INTEGER)
RETURNS (TAGE INTEGER)
AS 
               
BEGIN
  SELECT faellig FROM zkondi
   WHERE OID = :AOID
   INTO :TAGE;
  
  IF (:TAGE IS NULL) THEN TAGE = 0; ELSE TAGE = :TAGE;
  SUSPEND;
END ^

