ALTER PROCEDURE P_STARTIKEL (ASTOID INTEGER,
AMENGE D_DOUBLE)
RETURNS (ASOID D_INTEGER,
AASOID D_INTEGER,
AARTOID D_INTEGER,
AARTNR D_VARCHAR60,
MENGE D_DOUBLE)
AS 
   BEGIN   BEGIN    FOR Select SOID, ASOID, ARTOID, Artnr, (Anzahl*:AMenge) from Stuecklistenartikel where SOID = :ASTOID   Into :ASOID, :AASOID, :AARTOID, :AArtnr, :Menge DO    BEGIN   SUSPEND;      IF ((AASOID >0 ) AND (AASOID <> ASOID)) THEN    BEGIN        FOR Select * from P_STARTIKEL(:AASOID, :MENGE) into :ASOID, :AASOID, :AARTOID, :AArtnr, :Menge DO        SUSPEND; END  END END END ^

ALTER PROCEDURE P_STARTIKELKUNDE (AADROID INTEGER,
ASTOID INTEGER)
RETURNS (ASOID D_INTEGER,
AASOID D_INTEGER,
AARTOID D_INTEGER,
AARTNR D_VARCHAR60)
AS 
    DECLARE VARIABLE ADRSTID 
INTEGER;
    DECLARE VARIABLE ASSTID INTEGER;
  BEGIN
   IF (:AADROID < 0) THEN
   BEGIN
     FOR Select SOID, ASOID, ARTOID, Artnr
          from Stuecklistenartikel where SOID = 
:ASTOID
          Into :ASOID, :AASOID, :AARTOID, :AArtnr 
DO
            BEGIN
              SUSPEND;
               ASSTID = coalesce(AASOID, 0);
               IF ((ASSTID >0 ) AND (ASSTID <> 
ASOID)) THEN
               BEGIN
                 FOR Select * from 
P_STARTIKELKUNDE(-222, :ASSTID) into 
:ASOID, :AASOID, :AARTOID, :AArtnr DO
                 SUSPEND;
               END

            END
          SUSPEND;
   END

   IF (:AADROID > 0) THEN
   BEGIN
     FOR SELECT ASOID FROM 
P_KUNDARTIKELALL(:AADROID) into 
:ADRSTID DO
       BEGIN
          FOR Select SOID, ASOID, ARTOID, Artnr
            from Stuecklistenartikel where SOID = 
:ADRSTID
              Into :ASOID, :AASOID, :AARTOID, 
:AArtnr DO 
              BEGIN
              SUSPEND;
               ASSTID = coalesce(AASOID, 0);
               IF ((ASSTID >0 ) AND (ASSTID <> 
ASOID)) THEN
               BEGIN
                 FOR Select * from 
P_STARTIKELKUNDE(-222, :ASSTID) into 
:ASOID, :AASOID, :AARTOID, :AArtnr DO
                 SUSPEND;
               END
               
            END
            
            SUSPEND;
       END
       SUSPEND;
   END
END ^

ALTER PROCEDURE P_STATUS (AOID INTEGER)
RETURNS (STATUS VARCHAR(60) CHARACTER SET NONE)
AS 
   BEGIN  SELECT STATUS FROM BELEGSTATUS WHERE OID = :AOID INTO :STATUS;  SUSPEND; END ^

ALTER PROCEDURE P_STBEREIT RETURNS (ASOID D_INTEGER,
AASOID D_INTEGER,
AARTOID D_INTEGER,
AARTNR D_VARCHAR60,
MENGE D_DOUBLE,
BEGINN D_DATE_LEER)
AS 
   DECLARE Variable BArtoid Integer;  DECLARE Variable BMenge Integer; DECLARE Variable BBEGINN D_Date_Leer; BEGIN  BEGIN   FOR select ArtOID, Menge, Beginndatum from ProduktionBereit where coalesce(Status, 0) <> -1     into :BArtoid, :Bmenge, :Beginn Do BEGIN  FOR Select ASOID, AASOID, AARTOID, AArtnr, Menge from P_Startikel(:BArtOID, :BMenge)       Into :ASOID, :AASOID, :AARTOID, :AArtnr, :Menge Do SUSPEND; END END END ^

ALTER PROCEDURE P_TOPBOT (AARTOID INTEGER,
ASTUECKOID INTEGER)
RETURNS (TOPBOT VARCHAR(10) CHARACTER SET NONE)
AS 
   BEGIN  select cast(list(DISTINCT FARBNR, '/') as varchar(10)) from Stuecklistenartikel where artoid = :AARTOID  and soid = :ASTUECKOID Into TOPBOT;  SUSPEND; END ^

ALTER PROCEDURE P_VERFUEGBAR (AOID INTEGER)
RETURNS (BESTAND NUMERIC(15, 2))
AS 
                  

DECLARE VARIABLE ZUB NUMERIC (15,2);
DECLARE VARIABLE AB NUMERIC (15,2);
DECLARE VARIABLE AB2 NUMERIC (15,2);

BEGIN
 SELECT SUM(GELIEFERT) FROM BELEGPOS,BELEG
  WHERE (BELEG.BELEGART = 205
  OR BELEG.BELEGART = 405)
  AND BELEGPOS.SOID = BELEG.OID
  AND BELEGPOS.ARTOID = :AOID
  INTO :ZUB;

 SELECT SUM(STCK) FROM BELEGPOS,BELEG
  WHERE (BELEG.BELEGART = 203
  OR BELEG.BELEGART = 206 
  OR BELEG.BELEGART = 403)
  AND BELEGPOS.SOID = BELEG.OID
  AND ARTOID = :AOID
  INTO :AB;

 SELECT SUM(STCK) FROM BELEGPOS,BELEG
  WHERE (BELEG.BELEGART = 200
  OR BELEG.BELEGART = 300 
  OR BELEG.BELEGART = 400)
  AND BELEGPOS.SOID = BELEG.OID
  AND ARTOID = :AOID
  INTO :AB2;

  IF (:ZUB IS NULL) THEN ZUB = 0; ELSE ZUB = :ZUB;

  IF (:AB IS NULL) THEN AB = 0; ELSE AB = :AB;

  IF (:AB2 IS NULL) THEN AB2 = 0; ELSE AB2 = :AB2;

  BESTAND = ZUB  - AB - AB2;
SUSPEND;
END ^
SET TERM ; ^
COMMIT WORK ;
SET AUTODDL ON;
SET TERM ^ ;

/* Triggers only will work for SQL triggers */
CREATE TRIGGER T_FAELLIG_BI FOR BELEG 
ACTIVE BEFORE INSERT POSITION 0 
AS

DECLARE VARIABLE TAGE INTEGER;
DECLARE Variable ZAHLUNG NUMERIC(15,2);

BEGIN
    IF (NEW.BELEGART <> 104) THEN
  BEGIN
  EXECUTE PROCEDURE P_RECHNUNGFAELLIG NEW.ZKONDI
  RETURNING_VALUES :TAGE;
  NEW.FAELLIG = NEW.BELEGDATUM + :TAGE;
  END

  EXECUTE PROCEDURE P_BELEGOFFEN NEW.OID
   RETURNING_VALUES :ZAHLUNG;

  IF (NEW.BELEGART = 3) THEN NEW.OFFEN = NEW.BRUTTO - :ZAHLUNG;
END ^

CREATE TRIGGER T_HAUPTAUFTRAG_AI FOR BELEG 
ACTIVE BEFORE INSERT POSITION 0 
AS
BEGIN
  IF (BELEG.BELEGART = 1 AND BELEG.HAUPTAUFTRAG IS NULL) THEN BELEG.HAUPTAUFTRAG = BELEG.NUMMER;
END ^

CREATE TRIGGER LAGERBUCHUNGTRIGGER1 FOR LAGERBUCHUNG 
ACTIVE AFTER DELETE POSITION 0 
AS
BEGIN
  INSERT INTO LAGERBUCHUNG_HIST (OID, ARTOID, POSOID, BELEGOID, LAGEROID,
     AUFTRAGOID, BUCHUNGSOID, MENGE, BEMERKUNG, DATUM, STORNO)
    VALUES(OLD.OID, OLD.ARTOID, OLD.POSOID, OLD.BELEGOID, OLD.LAGEROID,
     OLD.AUFTRAGOID, OLD.BUCHUNGSOID, OLD.MENGE, OLD.BEMERKUNG, OLD.DATUM, OLD.STORNO);
END ^

COMMIT WORK ^
SET TERM ; ^
